{"query":"query($q: String!, $first: Int!, $after: String) {
  search(type: ISSUE, query: $q, first: $first, after: $after) {
    issueCount
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on Issue {
        number title url body createdAt updatedAt
        author { login } authorAssociation
        labels(first: 10) { nodes { name } }
        reactionGroups { content reactors { totalCount } }
        comments { totalCount }
        firstComments: comments(first: 30) { nodes { id url body createdAt author { login } authorAssociation isMinimized reactionGroups { content reactors { totalCount } } } }
        lastComments: comments(last: 15) { nodes { id url body createdAt author { login } authorAssociation isMinimized reactionGroups { content reactors { totalCount } } } }
      }
    }
  }
}","variables":{"q":"repo:date-fns/date-fns is:issue is:open ("3.6.0" OR "v3.6.0") sort:reactions-desc","first":25,"after":null}}
